// Phụ tùng chưa đặt `minStock` riêng — quy tắc "Cảnh báo tồn thấp" hiện có vẫn bắt được
// nhờ ngưỡng chung mặc định, nhưng ngưỡng chung không phân biệt được lọc dầu (tiêu thụ
// nhanh) với hộp số (tiêu thụ hiếm). Sắp theo tồn kho tăng dần: mã đang tồn thấp nhất cần
// đặt ngưỡng trước tiên.
const d = $json;
const sample = d.sample || [];

const rows = sample.map(p => `<tr><td>${p.code}</td><td>${p.name}</td><td>${p.category}</td><td align="right">${p.stock}</td></tr>`).join('');

const html = `<h2>📐 ${d.count} phụ tùng chưa đặt ngưỡng tồn kho riêng</h2>`
  + `<p>Danh sách dưới là ${sample.length} mã đang tồn thấp nhất (ưu tiên đặt ngưỡng trước):</p>`
  + `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">`
  + `<tr><th>Mã</th><th>Tên phụ tùng</th><th>Nhóm</th><th>Tồn</th></tr>${rows}</table>`
  + `<p style="color:#888;font-size:12px">${d.company_name} — ${new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}</p>`;

return { json: {
  email_to: d.company_email || '',
  email_subject: `📐 ${d.count} phụ tùng còn thiếu ngưỡng tồn kho tối thiểu`,
  email_html: html
} };
